use vstd::prelude::*;

verus! {
    // Specification function: all elements in the vector `v` are equal to `x`.
    spec fn all_equal(v: &Vec<i32>, x: i32) -> bool {
        forall |i: int| (0 <= i && i < v.len()@) ==> v.index(i) == x
    }

    // The function implementation.
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            all_equal(&result, 1),
    {
        let n = a.len();

        let mut res = Vec::<i32>::new();
        let mut i: usize = 0;

        // Loop from 0 up to n, building a vector of all ones.
        while i < n
            invariant
                i <= n,
                res.len() == i,
                all_equal(&res, 1),
            decreases n - i,
        {
            res.push(1);
            i = i + 1;
        }

        res
    }
}
